  "name": "api-service",
  "version": "1.0.0",
  "description": "API service with health check endpoint",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "nodemon app.js",
    "test": "echo \"Error: no test specified\" && exit 1"
  },
  "dependencies": {
