const express = require('express');
const { Client } = require('pg');
const app = express();

// Database connection setup
const DATABASE_URL = process.env.DATABASE_URL || 'postgres://localhost:5432/postgres';

// Database health check function
async function checkDatabaseHealth() {
  const client = new Client({
    connectionString: DATABASE_URL,
    // Add timeout for health checks
    connectionTimeoutMillis: 5000,
    query_timeout: 5000
  });

  try {
    await client.connect();
    // Try a simple query
    await client.query('SELECT 1 as health_check');
    await client.end();
    return { healthy: true, message: 'Database connection successful' };
  } catch (error) {
    // Ensure client is properly closed even on error
    try {
      await client.end();
    } catch (e) {
      // Ignore cleanup errors
    }
    return { 
      healthy: false, 
      message: `Database connection failed: ${error.message}` 
    };
  }
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// New healthz endpoint for k8s readiness probe
app.get('/healthz', async (req, res) => {
  try {
    const dbHealth = await checkDatabaseHealth();

    if (dbHealth.healthy) {
      // Return 200 OK when database is reachable
      res.status(200).json({ db: 'ok' });
    } else {
      // Return 503 Service Unavailable when database check fails
      res.status(503).json({ 
        db: 'error',
        message: dbHealth.message
      });
    }
  } catch (error) {
    // Catch any unexpected errors
    res.status(503).json({ 
      db: 'error',
      message: `Health check failed: ${error.message}`
    });
  }
});

app.get('/users', (req, res) => {
