// Test script to verify the healthz endpoint
const app = require('./app.js');
const request = require('supertest');

// Mock the DATABASE_URL for testing
process.env.DATABASE_URL = 'postgres://test:test@localhost:5432/testdb';

describe('Healthz Endpoint', () => {
  it('should return 200 when DB is healthy', async () => {
    // Mock pg Client to simulate successful connection
    const mockClient = {
      connect: jest.fn().mockResolvedValue(),
      query: jest.fn().mockResolvedValue({ rows: [{ health_check: 1 }] }),
      end: jest.fn().mockResolvedValue()
    };

    jest.mock('pg', () => ({
      Client: jest.fn(() => mockClient)
    }));

    const response = await request(app).get('/healthz');
    expect(response.status).toBe(200);
    expect(response.body).toEqual({ db: 'ok' });
  });

  it('should return 503 when DB connection fails', async () => {
    // Mock pg Client to simulate connection failure
    const mockClient = {
      connect: jest.fn().mockRejectedValue(new Error('Connection refused')),
      end: jest.fn().mockResolvedValue()
    };

    jest.mock('pg', () => ({
      Client: jest.fn(() => mockClient)
    }));

    const response = await request(app).get('/healthz');
    expect(response.status).toBe(503);
    expect(response.body.db).toBe('error');
    expect(response.body.message).toContain('Database connection failed');
  });
});

console.log('Test file created - would require Jest/supertest to run');

