const { Client } = require('pg');
const app = express();

// PostgreSQL connection setup
const client = new Client({
  connectionString: process.env.DATABASE_URL || 'postgres://localhost:5432/testdb'
});

// Database connection state
let dbConnected = false;

// Try to connect to PostgreSQL
async function connectToDatabase() {
  try {
    await client.connect();
    dbConnected = true;
    console.log('Connected to PostgreSQL database');
  } catch (error) {
    console.error('PostgreSQL connection error:', error.message);
    dbConnected = false;
  }
}

// Initial connection attempt
connectToDatabase();

// Health check endpoint
app.get('/healthz', async (req, res) => {
  try {
    // Check if database is connected
    if (!dbConnected) {
      throw new Error('Database not connected');
    }

    // Perform a simple query to verify database connectivity
    await client.query('SELECT 1');

    // Return 200 OK with status
    res.status(200).json({ db: 'ok' });
  } catch (error) {
    // Return 503 Service Unavailable on database failure
    res.status(503).json({ 
      db: 'error',
      message: error.message 
    });
  }
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Graceful shutdown
process.on('SIGTERM', async () => {
  if (dbConnected) {
    await client.end();
    console.log('PostgreSQL connection closed');
  }
  process.exit(0);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

