// Test script for the /healthz endpoint
const http = require('http');
const url = require('url');

// Test the healthz endpoint
function testHealthz() {
  return new Promise((resolve, reject) => {
    const options = {
      hostname: 'localhost',
      port: 3000,
      path: '/healthz',
      method: 'GET',
      headers: {
        'Accept': 'application/json'
      }
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        try {
          const response = JSON.parse(data);
          resolve({
            statusCode: res.statusCode,
            response: response
          });
        } catch (e) {
          reject(new Error(`Failed to parse response: ${e.message}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    req.end();
  });
}

// Run the test
async function runTest() {
  console.log('Testing /healthz endpoint...');

  try {
    const result = await testHealthz();
    console.log(`Status Code: ${result.statusCode}`);
    console.log(`Response: ${JSON.stringify(result.response, null, 2)}`);

    if (result.statusCode === 200 && result.response.db === 'ok') {
      console.log('✓ Health check passed!');
      return true;
    } else if (result.statusCode === 503) {
      console.log('✗ Health check failed (database not available)');
      console.log('Note: This is expected if DATABASE_URL is not configured or database is not running');
      return false;
    } else {
      console.log('✗ Unexpected response');
      return false;
    }
  } catch (error) {
    console.log(`✗ Error: ${error.message}`);
    console.log('Note: Make sure the server is running on port 3000');
    return false;
  }
}

// Export for use in other tests
module.exports = { testHealthz, runTest };

// Run if called directly
if (require.main === module) {
  runTest().then(success => {
    process.exit(success ? 0 : 1);
  });
}

