const envContent = fs.readFileSync('.env.test', 'utf8');
const envLines = envContent.split('\n');
const envVars = {};

// Parse .env file
for (const line of envLines) {
  if (line.trim() && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    if (key && valueParts.length > 0) {
      envVars[key.trim()] = valueParts.join('=').trim();
    }
  }
}

// Convert to JSON
const jsonData = JSON.stringify(envVars);

// Make POST request to CI secret sync endpoint
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/ci-secret-sync',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(jsonData)
  }
};

const req = http.request(options, (res) => {
  console.log(`Status Code: ${res.statusCode}`);

  let responseData = '';
  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log('Response:', responseData);
    if (res.statusCode === 200) {
      console.log('CI secret sync completed successfully');
    } else {
      console.error('CI secret sync failed');
      process.exit(1);
    }
  });
});

req.on('error', (error) => {
  console.error('Error making CI secret sync request:', error.message);
  // If the endpoint is not available (e.g., in local development),
  // we'll log a warning but not fail since this might be expected
  console.warn('Note: CI secret sync endpoint may not be available locally');
});

req.write(jsonData);
req.end();

