#!/usr/bin/env node

// CI secret-sync script
// Reads .env.test and POSTs to http://localhost:47301/api/ci-secret-sync
const fs = require('fs');
const http = require('http');

async function syncSecrets() {
  try {
    // Read .env.test file
    const envContent = fs.readFileSync('.env.test', 'utf8');

    // Parse environment variables
    const secrets = {};
    const lines = envContent.split('\n');

    lines.forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#')) {
        const equalsIndex = line.indexOf('=');
        if (equalsIndex !== -1) {
          const key = line.substring(0, equalsIndex).trim();
          const value = line.substring(equalsIndex + 1).trim();
          secrets[key] = value;
        }
      }
    });

    // Prepare request
    const postData = JSON.stringify(secrets);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/ci-secret-sync',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    console.log('Syncing secrets to CI...');

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Secrets synced successfully');
          process.exit(0);
        } else {
          console.error(`Secret sync failed with status ${res.statusCode}: ${data}`);
          process.exit(1);
        }
      });
    });

    req.on('error', (error) => {
      console.error(`Failed to connect to CI secret sync endpoint: ${error.message}`);
      console.log('Note: This may be expected if CI server is not running locally');
      process.exit(0); // Exit gracefully for local testing
    });

    req.write(postData);
    req.end();

  } catch (error) {
    console.error(`Error during secret sync: ${error.message}`);
    process.exit(1);
  }
}

// Run sync
syncSecrets();

