    // Exit with appropriate code for testing
    if (res.statusCode === 200 && data.includes('"db":"ok"')) {
      console.log('✓ Health check passed');
      process.exit(0);
    } else {
      console.log('✗ Health check failed');
      process.exit(1);
    }
  });
});

