#!/usr/bin/env node

const fs = require('fs');
const https = require('https');
const http = require('http');

// Read .env.test file
const envPath = '.env.test';

if (!fs.existsSync(envPath)) {
  console.error(`Error: ${envPath} not found`);
  process.exit(1);
}

try {
  const envContent = fs.readFileSync(envPath, 'utf8');

  // Parse the .env file into an object
  const envVars = {};
  const lines = envContent.split('\n');

  lines.forEach(line => {
    // Skip empty lines and comments
    if (line.trim() === '' || line.startsWith('#')) {
      return;
    }

    const [key, ...valueParts] = line.split('=');
    if (key && valueParts.length > 0) {
      envVars[key.trim()] = valueParts.join('=').trim();
    }
  });

  // Create the POST request
  const postData = JSON.stringify(envVars);
  const parsedUrl = new URL('http://localhost:47301/api/ci-secret-sync');

  const options = {
    hostname: parsedUrl.hostname,
    port: parsedUrl.port || 47301,
    path: parsedUrl.pathname,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  const req = (parsedUrl.protocol === 'https:' ? https : http).request(options, (res) => {
    let data = '';

    res.on('data', (chunk) => {
      data += chunk;
    });

    res.on('end', () => {
      if (res.statusCode >= 200 && res.statusCode < 300) {
        console.log('Secret sync completed successfully');
        process.exit(0);
      } else {
        console.error(`Secret sync failed with status ${res.statusCode}: ${data}`);
        process.exit(1);
      }
    });
  });

  req.on('error', (error) => {
    console.error(`Request error: ${error.message}`);
    // Even if the sync fails, we continue with the PR (CI will handle validation)
    console.log('Note: CI will handle secret validation during merge check');
    process.exit(0);
  });

  req.write(postData);
  req.end();

} catch (error) {
  console.error(`Error syncing secrets: ${error.message}`);
  // Even if we can't sync, continue (CI will handle validation)
  console.log('Note: CI will handle secret validation during merge check');
  process.exit(0);
}

