// CI secret-sync script
// Reads .env.test and POSTs its contents as JSON to http://localhost:47301/api/ci-secret-sync

const fs = require('fs');
const https = require('https');
const http = require('http');

async function syncSecrets() {
  try {
    // Read .env.test file
    const envContent = fs.readFileSync('.env.test', 'utf8');

    // Parse env file into key-value pairs
    const envVars = {};
    const lines = envContent.split('\n');

    for (const line of lines) {
      // Skip comments and empty lines
      if (line.trim() === '' || line.startsWith('#')) {
        continue;
      }

      const equalsIndex = line.indexOf('=');
      if (equalsIndex !== -1) {
        const key = line.substring(0, equalsIndex).trim();
        const value = line.substring(equalsIndex + 1).trim();
        envVars[key] = value;
      }
    }

    console.log('Read env vars:', Object.keys(envVars));

    // Prepare the POST request
    const postData = JSON.stringify(envVars);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/ci-secret-sync',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    return new Promise((resolve, reject) => {
      const req = http.request(options, (res) => {
        console.log(`Status Code: ${res.statusCode}`);

        let data = '';
        res.on('data', (chunk) => {
          data += chunk;
        });

        res.on('end', () => {
          console.log('Response:', data);
          resolve({ statusCode: res.statusCode, data });
        });
      });

      req.on('error', (error) => {
        console.error('Request error:', error.message);
        reject(error);
      });

      // Write data to request body
      req.write(postData);
      req.end();
    });

  } catch (error) {
    console.error('Secret sync failed:', error.message);
    throw error;
  }
}

// Run the sync
syncSecrets().then(() => {
  console.log('Secret sync completed successfully');
  process.exit(0);
}).catch((error) => {
  console.error('Secret sync failed:', error);
  process.exit(1);
});

